 	ProfileLastUs := NowUs;
 END_IF
-Profile.LastUs[section] := ElapsedUs;
-Profile.MaxUs[section] := MAX(Profile.MaxUs[section], ElapsedUs);
+// A section can be booked twice in one call (PARSE_IN: before the state machines and after the receive), so
+// LastUs adds up within the call (ProfileBegin clears it) and MaxUs follows the per-call sum.
+Profile.LastUs[section] := Profile.LastUs[section] + ElapsedUs;
+Profile.MaxUs[section] := MAX(Profile.MaxUs[section], Profile.LastUs[section]);
 Profile.TotalUs[section] := Profile.TotalUs[section] + ElapsedUs;
